// One e-mail per clinic owner on the days that matter, plus one digest for Circle.
const s = $('Settings').first().json;
const res = $('Get due clinics').first().json;
const out = [];
const sar = (v) => v == null ? 'حسب الاتفاق' : `${v.toLocaleString('en')} ريال`;
const pay = `للتجديد تواصل معنا واتساب: https://wa.me/${s.circle_whatsapp}`;
for (const c of res.clinics || []) {
  const since = Math.floor((Date.now() - new Date(c.ends_at).getTime()) / 86400000);
  let subject = null, body = null;
  if ((c.state === 'trial') && [3, 1].includes(c.days_left)) {
    subject = `تجربتك في سيركل تنتهي بعد ${c.days_left} يوم`;
    body = `أهلاً ${c.clinic} 🌿\n\nتجربتك المجانية في سيركل تنتهي بعد ${c.days_left} يوم.\nللاستمرار بدون توقف للمساعد الذكي والحجوزات: ${sar(c.price_sar)} شهرياً.\n\n${pay}`;
  } else if (c.state === 'active' && [3, 1].includes(c.days_left)) {
    subject = `تجديد اشتراك سيركل بعد ${c.days_left} يوم`;
    body = `أهلاً ${c.clinic} 🌿\n\nاشتراكك في سيركل ينتهي بعد ${c.days_left} يوم.\nمبلغ التجديد: ${sar(c.price_sar)}.\n\n${pay}`;
  } else if (c.state === 'grace' && [1, 4, 6].includes(since)) {
    subject = 'اشتراك سيركل انتهى — المهلة سارية';
    body = `أهلاً ${c.clinic}\n\nانتهت مدة اشتراكك، وعندك مهلة ${7 - since} يوم قبل إيقاف المساعد الذكي على واتساب.\n\n${pay}`;
  } else if (c.state === 'expired' && since === 8) {
    subject = 'توقف المساعد الذكي في سيركل';
    body = `أهلاً ${c.clinic}\n\nتوقف المساعد الذكي لانتهاء الاشتراك. رسائل المرضى ما زالت تصل لصندوق المحادثات في لوحتك، وبياناتك محفوظة.\nجدّد ويرجع المساعد فوراً.\n\n${pay}`;
  }
  if (subject && c.owner_email) out.push({ json: { to: c.owner_email, subject, body } });
}
const list = (res.clinics || []).map((c) => `• ${c.clinic} — ${c.state} — ${c.days_left} يوم — ${sar(c.price_sar)} — ${c.phone || ''} ${c.owner_email || ''}`).join('\n');
if (list) out.push({ json: { to: s.founder_email, subject: `سيركل: ${res.count} عيادة تحتاج متابعة دفع`, body: `${list}\n\nسجّل أي دفعة من: ${s.circle_url}/ar/portal/admin` } });
return out;
